raw:
{
  "1": {
    "A": "最挤的一屏是第 2 张切块(核心指标 + 模拟视图):一组 4 个 KPI 数字、一张双课表图(含图注),共 2–3 种模块;模块间距约 3 个正文 line-height(约 150px),不挤。存在大半空白的一屏:最后一屏「背景信息」只有 4 行字,其余全是空白。",
    "B": "结构与 A 完全相同:最挤一屏同样是核心指标 + 模拟视图,2–3 种模块,间距同样约 3 个 line-height;最后一屏「背景信息」同样只有 4 行、大半空白。",
    "better": "平"
  },
  "2": {
    "A": "区块内 gap 很小(标签与说明 4–6px,表格行距约 28px),section spacing 约 150px,约为组内 gap 的 3–5 倍,两级分明;但核心指标第一格内部多了一行说明,组内层级与其余三格不同。",
    "B": "同样是「小 gap + 大 section spacing」的两级结构,数值与 A 一致;核心指标四格内部结构完全一致。",
    "better": "平"
  },
  "3": {
    "A": "无。表格顶部细线只用于分隔表头与数据行;模拟视图下方浅灰条只用于分隔「原界面」与「红色盲」两组图;全页没有多余的 card、圆角或阴影。",
    "B": "无。与 A 相同,只有表格表头细线和模拟视图下的灰色分隔条,均可说清作用。",
    "better": "平"
  },
  "4": {
    "A": "约 5 级:h1 标题 / h2 区块标题 / 区块副标题(灰色 caption)/ 正文与表格正文 / KPI 大数字与表下脚注 caption;KPI 页额外多出一处红色小字强调「要求 ≥4.5:1」。",
    "B": "同样的 5 级,层级与字号和 A 一致;KPI 页没有任何额外强调,强调点只有表格里的「不达标」「高」。",
    "better": "B"
  },
  "5": {
    "A": "accent 只有红色一种:表格中的「不达标」「高」,以及核心指标里的「要求 ≥4.5:1」;视觉重量最大的一块是模拟视图里的课表色块(即被分析的数据本身);分隔线均为 1px 浅灰,线宽一致。",
    "B": "accent 同样只有红色,只出现在表格的「不达标」「高」;最大视觉重量同为模拟视图的课表色块;线宽一致。",
    "better": "平"
  },
  "6": {
    "A": "四个 KPI 中第一个比其余三个多一行红色说明,同一组同类数字的组件形式不完全一致;其余同类内容(三张表、两组数字)形式统一。",
    "B": "四个 KPI 形式完全一致(数字 + 单位 + 一行标签);三张表、类型分布与核心指标两组数字也各自统一。",
    "better": "B"
  },
  "7": {
    "A": "核心指标一排四个数字的底边不齐(第一列多一行红字,整排基线呈锯齿);其余模块左边界都落在标签列与页边两条线上,留白基本成矩形。",
    "B": "核心指标四列等高、底边齐平,其余模块左边界同样落在标签列与页边两条线上,留白成规整矩形。",
    "better": "B"
  },
  "better": "B",
  "reason": "两版几乎同构,但 B 版核心指标一排四个数字等高等宽、无额外红色注释,字体层级和基线对齐更干净;A 版在第一格多出一行红字,使该列变高、整排底边不齐,也多了一处削弱其他强调的红字。",
  "next": [
    {
      "where": "最后一屏「背景信息」区块",
      "problem": "整屏只有 4 行文字,下方大半为空白,信息密度过低,与上一屏之间的 section spacing 也被拉得过大;建议与「问题明细」合并到一屏或压缩页高。"
    },
    {
      "where": "「类型分布」区块(第 3 张切块下半)",
      "problem": "一屏只有 3 个数字(5个/5个/5个),上下留白超过 200px,属留白过多,可与核心指标或下一张对比度表合并。"
    },
    {
      "where": "「对比度」表格下方的脚注「对比度按 WCAG 2.2 AA 正文标准 4.5:1;文字均为 #FFFFFF」",
      "problem": "脚注悬在表格中部,既没与表格左边界对齐、也没与右边界对齐,造成 L 形留白;应与表格左边界对齐或整体右对齐。"
    },
    {
      "where": "「模拟视图」右侧的红色盲课表",
      "problem": "表格超出页面右边界被裁切,与左侧原界面课表宽度不一致,右侧留白不成矩形;应缩放至同一栏宽或改并排为上下排列。"
    }
  ]
}
